const body = $('Webhook').first().json.body;
const files = body.files || [];
const bucket = body.bucket;
const prefix = body.prefix || '';

const results = files.map((file, index) => {
  const key = prefix ? `${prefix}/${file.name}` : file.name;
  return {
    index: index,
    name: file.name,
    key: key,
    bucket: bucket,
    url: `https://${bucket}.s3.amazonaws.com/${key}`,
    status: 'ready'
  };
});

return [{ json: { provider: 's3', bucket: bucket, results: results, total: files.length } }];

const body = $('Webhook').first().json.body;
const files = body.files || [];
const bucket = body.bucket;
const prefix = body.prefix || '';

const results = files.map((file, index) => {
  const path = prefix ? `${prefix}/${file.name}` : file.name;
  return {
    index: index,
    name: file.name,
    path: path,
    bucket: bucket,
    url: `https://storage.googleapis.com/${bucket}/${path}`,
    status: 'ready'
  };
});

return [{ json: { provider: 'gcs', bucket: bucket, results: results, total: files.length } }];

const body = $('Webhook').first().json.body;
const files = body.files || [];
const container = body.container || body.bucket;
const prefix = body.prefix || '';
const accountName = body.credentials?.account_name || 'account';

const results = files.map((file, index) => {
  const blobName = prefix ? `${prefix}/${file.name}` : file.name;
  return {
    index: index,
    name: file.name,
    blob_name: blobName,
    container: container,
    url: `https://${accountName}.blob.core.windows.net/${container}/${blobName}`,
    status: 'ready'
  };
});

return [{ json: { provider: 'azure', container: container, results: results, total: files.length } }];

const body = $('Webhook').first().json.body;
const files = body.files || [];
const bucket = body.bucket;
const prefix = body.prefix || '';
const accountId = body.credentials?.account_id || 'account';

const results = files.map((file, index) => {
  const key = prefix ? `${prefix}/${file.name}` : file.name;
  return {
    index: index,
    name: file.name,
    key: key,
    bucket: bucket,
    url: `https://${accountId}.r2.cloudflarestorage.com/${bucket}/${key}`,
    status: 'ready'
  };
});

return [{ json: { provider: 'cloudflare', bucket: bucket, results: results, total: files.length } }];

const items = $input.all();

const results = items.map(item => {
  return {
    json: {
      success: true,
      data: {
        provider: item.json.provider,
        bucket: item.json.bucket || item.json.container,
        files: item.json.results,
        summary: {
          total: item.json.total,
          uploaded: 0,
          pending: item.json.total,
          failed: 0
        }
      },
      meta: {
        provider: 'cloud-uploader',
        target: item.json.provider
      }
    }
  };
});

return results;

